-- V1.8.0 — COACHIP insight store (epic bd-sex15q; m-insights bd-sex15q.14). From the c-insights contract
-- (INSIGHTS_SCHEMA v1.1, unchanged below this header). Flyway-style versioned migration (D8). Applied to sandbox
-- (olvritwoqujtjvwfulbh) by the lander after the train; never to prod without the operator's go. Rollback: ROLLBACK_V1.8.0__coachip_insights.sql.
-- Generated by c-insights' build_schema.py from one spec; a schema change goes there first.
--
-- WHAT. The nightly COACHIP job's stored outputs (facts, signals, moments, rollups, circle, model runs, job runs),
-- the W/I lookups and crosswalk, the per-coach teacher code space, the append-only audit log, and the coaching loop
-- (steps, step checks, RM notes). Routes read these tables only; nothing reads analysis_data from a route.
-- WHY NEW TABLES (schema-first, root rule 15). analysis_data is rewritten whole by ~20 writers (DATA_MAP §3);
-- nothing COACHIP computes may live there. No existing table holds per-W counts, codes or steps.
-- DATA CLASSIFICATION (D6): every column carries COMMENT '[Public|Internal|Confidential] ...'. Confidential =
-- teacher_key only (HMAC pseudonym, server only). No column holds a name, a contact number, a teacher's users.id,
-- a transcript quote or notable_moments[].named_student (B1, B21). Staff ids (coach, RM) are Internal.
-- OWNER (D7): COACHIP / m-insights (bd-sex15q.14). STEWARD: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.
-- RETENTION (D27, PENDING item 7 default A): clips deleted 8 weeks after the session's last window closes
-- (clip_status -> expired); derived rows are versioned, never hard-deleted by the job; the audit log is kept.
-- IDEMPOTENT: IF NOT EXISTS / guarded CREATE TYPE throughout. ORDER: safe before the code (no reader while the
-- portal_coachip flags are absent). Requires Postgres >= 12 (generated columns); sandbox and prod run 17.

-- NO BEGIN/COMMIT: migrate.js sends this file to rpc/exec_sql (a plpgsql EXECUTE), which refuses transaction control (0A000); the one RPC call is already one transaction.

-- ── ENUM types (D15) ─────────────────────────────────────────────────────────────────────────────────
DO $$ BEGIN CREATE TYPE coachip_status AS ENUM ('ok', 'insufficient', 'failed', 'mismatch'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_status IS '[Public] the state of one fact, signal or rollup; never rendered as a zero (B10)';
DO $$ BEGIN CREATE TYPE coachip_signal_source AS ENUM ('lp_fidelity', 'fico_v3', 'fico_v4', 'fico17', 'coachip_detector', 'egra', 'code'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_signal_source IS '[Public] which instrument produced a signal; a window reads one source per W (B19)';
DO $$ BEGIN CREATE TYPE coachip_signal_role AS ENUM ('primary', 'supporting', 'never'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_signal_role IS '[Public] the crosswalk role of an instrument for one W: primary is counted, supporting is shown, never is not read';
DO $$ BEGIN CREATE TYPE coachip_moment_kind AS ENUM ('missing', 'good', 'phonics'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_moment_kind IS '[Public] what a stored moment shows';
DO $$ BEGIN CREATE TYPE coachip_confidence AS ENUM ('high', 'medium', 'none'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_confidence IS '[Public] how the moment''s second was found (DESIGN §5)';
DO $$ BEGIN CREATE TYPE coachip_gloss_status AS ENUM ('ok', 'blocked', 'failed', 'not_applicable', 'pending', 'not_evaluated', 'paused'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_gloss_status IS '[Public] the state of a moment''s one-line gloss';
DO $$ BEGIN CREATE TYPE coachip_run_status AS ENUM ('ok', 'blocked', 'failed', 'not_applicable', 'pending'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_run_status IS '[Public] the state of one model call (x-analysis COST §5)';
DO $$ BEGIN CREATE TYPE coachip_failure_class AS ENUM ('http', 'timeout', 'empty', 'unparseable', 'truncated', 'gate', 'input_missing', 'cap_reached', 'env_mismatch', 'upstream'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_failure_class IS '[Public] why something failed; one closed list so the method sheet can count them';
DO $$ BEGIN CREATE TYPE coachip_clip_status AS ENUM ('ready', 'pending', 'failed', 'expired'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_clip_status IS '[Public] the pre-cut clip object; expired = deleted under the retention rule, the full recording still plays';
DO $$ BEGIN CREATE TYPE coachip_scope_kind AS ENUM ('coach', 'school', 'sector'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_scope_kind IS '[Public] the scope a rollup or a step belongs to';
DO $$ BEGIN CREATE TYPE coachip_intervention_level AS ENUM ('teacher', 'school', 'sector'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_intervention_level IS '[Public] who an intervention is run with (DESIGN §6)';
DO $$ BEGIN CREATE TYPE coachip_step_status AS ENUM ('open', 'completed', 'deferred', 'cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_step_status IS '[Public] a coaching step''s life';
DO $$ BEGIN CREATE TYPE coachip_tick AS ENUM ('pending', 'yes', 'no'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_tick IS '[Public] the coach''s own did-it-work tick (the primary check)';
DO $$ BEGIN CREATE TYPE coachip_check_hit AS ENUM ('hit', 'partial', 'miss'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_check_hit IS '[Public] one later recording against a step''s check signal';
DO $$ BEGIN CREATE TYPE coachip_note_status AS ENUM ('sent', 'seen', 'set', 'dismissed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_note_status IS '[Public] an RM follow-up note''s life';
DO $$ BEGIN CREATE TYPE coachip_analysis AS ENUM ('gloss', 'phonics', 'homework'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_analysis IS '[Public] which model analysis a run belongs to';
DO $$ BEGIN CREATE TYPE coachip_run_purpose AS ENUM ('primary', 'fallback', 'recheck', 'drift_audit'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_run_purpose IS '[Public] why a model call was made: the live call, the supplier fallback, the 5% re-check or the monthly audit';
DO $$ BEGIN CREATE TYPE coachip_job_status AS ENUM ('running', 'ok', 'partial', 'failed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_job_status IS '[Public] one night''s job run';
DO $$ BEGIN CREATE TYPE coachip_phonics_gate AS ENUM ('testing', 'ok', 'paused'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_phonics_gate IS '[Public] the phonics detector''s gate (O8); not named coachip_phonics_state, which is the table (SPEC v2 §4 collision)';
DO $$ BEGIN CREATE TYPE coachip_stat_kind AS ENUM ('median', 'mean'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_stat_kind IS '[Public] a derived statistic''s kind (B5 add)';
DO $$ BEGIN CREATE TYPE coachip_stat_unit AS ENUM ('min', 's'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_stat_unit IS '[Public] a derived statistic''s unit';
DO $$ BEGIN CREATE TYPE coachip_step_verdict AS ENUM ('executed', 'partial', 'not_done', 'not_adjudicable', 'substituted', 'not_reached'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_step_verdict IS '[Public] one plan step''s verdict on the S4 chapter strip; not_reached = not_done after the lesson ran out of time (grey, G7)';
DO $$ BEGIN CREATE TYPE coachip_language AS ENUM ('ur', 'en'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_language IS '[Public] a child-result cell''s test language';
DO $$ BEGIN CREATE TYPE coachip_cell_status AS ENUM ('ok', 'insufficient', 'not_measured', 'not_graded'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_cell_status IS '[Public] a child-result cell: ok at >= 5 tested; insufficient below; not_measured for a gap subtask; not_graded before scoring exists';
DO $$ BEGIN CREATE TYPE coachip_audit_action AS ENUM ('decode', 'clip', 'full_audio', 'note_sent', 'circle_play'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TYPE coachip_audit_action IS '[Public] what an audited read or send was (D20)';

-- ── coachip_weaknesses ─────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_weaknesses (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  w_id                       text NOT NULL UNIQUE CHECK (w_id ~ '^W-[A-Z0-9-]+$'),
  parent_w_id                text REFERENCES coachip_weaknesses (w_id),
  primary_source             coachip_signal_source NOT NULL,
  pedagogical_weight         numeric(3,2) NOT NULL CHECK (pedagogical_weight BETWEEN 0 AND 1),
  is_s1_eligible             boolean NOT NULL,
  is_s7                      boolean NOT NULL,
  is_cause_line              boolean NOT NULL DEFAULT false,
  short_name_en              text NOT NULL CHECK (length(short_name_en) BETWEEN 1 AND 60),
  short_name_ur              text NOT NULL CHECK (length(short_name_ur) BETWEEN 1 AND 60),
  library_version            text NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  CHECK (parent_w_id IS DISTINCT FROM w_id)
);
COMMENT ON TABLE coachip_weaknesses IS 'The W catalogue (DESIGN §4, SPEC v2 §0.17): ids, weights and short names; long text stays in INTERVENTIONS.json. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_weaknesses.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_weaknesses.w_id IS '[Public] stable W id, e.g. W-IP-TIME';
COMMENT ON COLUMN coachip_weaknesses.parent_w_id IS '[Public] the parent W for a sub-row (W-IP for W-IP-TIME)';
COMMENT ON COLUMN coachip_weaknesses.primary_source IS '[Public] the instrument whose signal is counted for this W (FICO_CROSSWALK)';
COMMENT ON COLUMN coachip_weaknesses.pedagogical_weight IS '[Public] ranking weight (WEAKNESS_MAP §E)';
COMMENT ON COLUMN coachip_weaknesses.is_s1_eligible IS '[Public] may rank as a move on S1';
COMMENT ON COLUMN coachip_weaknesses.is_s7 IS '[Public] a child-result row shown on S7 only';
COMMENT ON COLUMN coachip_weaknesses.is_cause_line IS '[Public] recorded as a signal but shown only as its parent''s cause line (W-EXIT-TIME)';
COMMENT ON COLUMN coachip_weaknesses.short_name_en IS '[Public] short name, English';
COMMENT ON COLUMN coachip_weaknesses.short_name_ur IS '[Public] short name, Urdu';
COMMENT ON COLUMN coachip_weaknesses.library_version IS '[Public] INTERVENTIONS.json version the row was seeded from';
COMMENT ON COLUMN coachip_weaknesses.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_weaknesses.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_weaknesses_updated_at ON coachip_weaknesses;
CREATE TRIGGER coachip_weaknesses_updated_at BEFORE UPDATE ON coachip_weaknesses FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_weaknesses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_weaknesses ON coachip_weaknesses;
CREATE POLICY service_role_coachip_weaknesses ON coachip_weaknesses FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_weaknesses TO service_role;

-- ── coachip_weakness_signals ───────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_weakness_signals (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  w_id                       text NOT NULL REFERENCES coachip_weaknesses (w_id),
  source                     coachip_signal_source NOT NULL,
  indicator_id               text NOT NULL CHECK (indicator_id ~ '^([A-F][0-9]{1,2}|phase:[a-z_|]+|(code|flag):[a-z_]+|E[0-9]{1,2}|M[0-9]|-)$'),
  scale_min                  smallint,
  scale_max                  smallint,
  hit_rule                   text NOT NULL CHECK (length(hit_rule) BETWEEN 1 AND 200),
  role                       coachip_signal_role NOT NULL,
  crosswalk_version          text NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (w_id, source, indicator_id),
  CHECK (scale_min IS NULL OR scale_max > scale_min)
);
COMMENT ON TABLE coachip_weakness_signals IS 'The crosswalk as rows (WEAKNESS_MAP §F S18): per W, each instrument''s id, scale, hit rule and role. One source for screens, the job and the check strip. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_weakness_signals.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_weakness_signals.w_id IS '[Public] the W';
COMMENT ON COLUMN coachip_weakness_signals.source IS '[Public] the instrument';
COMMENT ON COLUMN coachip_weakness_signals.indicator_id IS '[Public] FICO id (C1), fidelity phase (phase:independent), a code leg or detector flag (code:sent_home, flag:letter_name_routine_only) or EGRA subtask (E4); ''-'' when the instrument has none';
COMMENT ON COLUMN coachip_weakness_signals.scale_min IS '[Public] lowest score on that instrument''s scale (1 on v3, 0 on v4); null for a phase';
COMMENT ON COLUMN coachip_weakness_signals.scale_max IS '[Public] highest score (4 on v3, 2 on v4)';
COMMENT ON COLUMN coachip_weakness_signals.hit_rule IS '[Public] the predicate in FICO_CROSSWALK notation, e.g. ''score <= 2''';
COMMENT ON COLUMN coachip_weakness_signals.role IS '[Public] primary (counted), supporting (shown, never counted) or never (not read)';
COMMENT ON COLUMN coachip_weakness_signals.crosswalk_version IS '[Public] FICO_CROSSWALK.md version';
COMMENT ON COLUMN coachip_weakness_signals.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_weakness_signals.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_weakness_signals_updated_at ON coachip_weakness_signals;
CREATE TRIGGER coachip_weakness_signals_updated_at BEFORE UPDATE ON coachip_weakness_signals FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_weakness_signals ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_weakness_signals ON coachip_weakness_signals;
CREATE POLICY service_role_coachip_weakness_signals ON coachip_weakness_signals FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_weakness_signals TO service_role;
CREATE UNIQUE INDEX IF NOT EXISTS uq_coachip_w_one_primary ON coachip_weakness_signals (w_id, source) WHERE role = 'primary';

-- ── coachip_interventions ──────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_interventions (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  i_id                       text NOT NULL UNIQUE CHECK (i_id ~ '^I-[A-Z0-9-]+$'),
  w_id                       text NOT NULL REFERENCES coachip_weaknesses (w_id),
  level                      coachip_intervention_level NOT NULL,
  rank_in_w                  smallint NOT NULL CHECK (rank_in_w >= 1),
  library_version            text NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (w_id, level, rank_in_w)
);
COMMENT ON TABLE coachip_interventions IS 'The I ids per W and level, in the experts'' order (DESIGN §6); text stays in INTERVENTIONS.json. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_interventions.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_interventions.i_id IS '[Public] stable intervention id';
COMMENT ON COLUMN coachip_interventions.w_id IS '[Public] the W it answers (sub-row first, LIBRARY_RULES)';
COMMENT ON COLUMN coachip_interventions.level IS '[Public] teacher (S5), school (S2/S8) or sector (S10)';
COMMENT ON COLUMN coachip_interventions.rank_in_w IS '[Public] the experts'' order within the W and level';
COMMENT ON COLUMN coachip_interventions.library_version IS '[Public] INTERVENTIONS.json version';
COMMENT ON COLUMN coachip_interventions.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_interventions.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_interventions_updated_at ON coachip_interventions;
CREATE TRIGGER coachip_interventions_updated_at BEFORE UPDATE ON coachip_interventions FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_interventions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_interventions ON coachip_interventions;
CREATE POLICY service_role_coachip_interventions ON coachip_interventions FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_interventions TO service_role;

-- ── coachip_job_runs ───────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_job_runs (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_date                   date NOT NULL,
  pipeline_version           text NOT NULL CHECK (pipeline_version ~ '^coachip-[0-9]+\.[0-9]+\.[0-9]+$'),
  env_ref                    text NOT NULL CHECK (env_ref IN ('olvritwoqujtjvwfulbh','staging','production')),
  started_at                 timestamptz NOT NULL,
  finished_at                timestamptz,
  attempt                    smallint NOT NULL DEFAULT 1 CHECK (attempt >= 1),
  sessions_seen              integer NOT NULL DEFAULT 0 CHECK (sessions_seen >= 0),
  sessions_ok                integer NOT NULL DEFAULT 0 CHECK (sessions_ok >= 0),
  sessions_failed            integer NOT NULL DEFAULT 0 CHECK (sessions_failed >= 0),
  model_calls                integer NOT NULL DEFAULT 0 CHECK (model_calls >= 0),
  cost_usd                   numeric(8,4) NOT NULL DEFAULT 0 CHECK (cost_usd >= 0),
  is_cap_hit                 boolean NOT NULL DEFAULT false,
  stages_done                text[] NOT NULL DEFAULT '{}',
  status                     coachip_job_status NOT NULL DEFAULT 'running',
  failure_class              coachip_failure_class,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (run_date, pipeline_version),
  CHECK (finished_at IS NULL OR finished_at >= started_at),
  CHECK ((status = 'failed') = (failure_class IS NOT NULL))
);
COMMENT ON TABLE coachip_job_runs IS 'One row per nightly run per pipeline version (NIGHTLY_JOB §9). Dry runs never write here. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_job_runs.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_job_runs.run_date IS '[Internal] the night the run covers (Asia/Karachi date)';
COMMENT ON COLUMN coachip_job_runs.pipeline_version IS '[Internal] provenance: the nightly job''s semantic version; a change starts a new series (B19)';
COMMENT ON COLUMN coachip_job_runs.env_ref IS '[Internal] the Supabase ref asserted before the first write';
COMMENT ON COLUMN coachip_job_runs.started_at IS '[Internal] start (UTC)';
COMMENT ON COLUMN coachip_job_runs.finished_at IS '[Internal] end (UTC); null while running';
COMMENT ON COLUMN coachip_job_runs.attempt IS '[Internal] re-runs of the same date increment this; the row is upserted';
COMMENT ON COLUMN coachip_job_runs.sessions_seen IS '[Internal] sessions read';
COMMENT ON COLUMN coachip_job_runs.sessions_ok IS '[Internal] facts written ok';
COMMENT ON COLUMN coachip_job_runs.sessions_failed IS '[Internal] facts written failed';
COMMENT ON COLUMN coachip_job_runs.model_calls IS '[Internal] model calls made';
COMMENT ON COLUMN coachip_job_runs.cost_usd IS '[Internal] summed model cost (OpenRouter usage.cost)';
COMMENT ON COLUMN coachip_job_runs.is_cap_hit IS '[Internal] the US$2 cap stopped new calls';
COMMENT ON COLUMN coachip_job_runs.stages_done IS '[Internal] stage names completed, in order';
COMMENT ON COLUMN coachip_job_runs.status IS '[Internal] run state';
COMMENT ON COLUMN coachip_job_runs.failure_class IS '[Internal] why the run failed, when it did';
COMMENT ON COLUMN coachip_job_runs.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_job_runs.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_job_runs_updated_at ON coachip_job_runs;
CREATE TRIGGER coachip_job_runs_updated_at BEFORE UPDATE ON coachip_job_runs FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_job_runs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_job_runs ON coachip_job_runs;
CREATE POLICY service_role_coachip_job_runs ON coachip_job_runs FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_job_runs TO service_role;

-- ── coachip_session_facts ──────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_session_facts (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id                 uuid NOT NULL REFERENCES coaching_sessions (id),
  teacher_key                text NOT NULL CHECK (teacher_key ~ '^[0-9a-f]{16}$'),
  school_id                  uuid NOT NULL REFERENCES schools (id),
  sector                     text NOT NULL CHECK (sector IN ('B.K','Sihala','Urban-I','Nilore','Urban-II','Tarnol')),
  recorded_at                timestamptz NOT NULL,
  is_observed                boolean NOT NULL,
  job_run_id                 uuid NOT NULL REFERENCES coachip_job_runs (id),
  grader_model               text NOT NULL CHECK (length(grader_model) BETWEEN 1 AND 120),
  framework_version          text NOT NULL CHECK (framework_version ~ '^(lp_fidelity|fico_v3|fico_v4|fico17|coachip_detector|egra|code)(:[A-Za-z0-9._-]+)?$'),
  pipeline_version           text NOT NULL CHECK (pipeline_version ~ '^coachip-[0-9]+\.[0-9]+\.[0-9]+$'),
  input_hash                 text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  status                     coachip_status NOT NULL,
  failure_class              coachip_failure_class,
  is_mismatch                boolean NOT NULL,
  is_unusable                boolean NOT NULL,
  is_duplicate               boolean NOT NULL,
  duplicate_of_session_id    uuid REFERENCES coaching_sessions (id),
  is_lp_linked               boolean NOT NULL,
  subject                    text CHECK (subject IS NULL OR length(subject) <= 40),
  grade                      smallint CHECK (grade IS NULL OR grade BETWEEN 1 AND 12),
  lesson_type                text CHECK (lesson_type IS NULL OR lesson_type IN ('literacy_phonics','literacy_text','maths','other')),
  audio_s                    integer CHECK (audio_s IS NULL OR audio_s >= 0),
  ends_at_s                  integer CHECK (ends_at_s IS NULL OR ends_at_s >= 0),
  last_stamp_s               integer CHECK (last_stamp_s IS NULL OR last_stamp_s >= 0),
  last_done_s                integer CHECK (last_done_s IS NULL OR last_done_s >= 0),
  is_short_of_audio          boolean,
  is_ran_out_of_time         boolean,
  is_time_remained           boolean,
  is_sent_home               boolean,
  is_stamped                 boolean NOT NULL DEFAULT true,
  computed_at                timestamptz NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (session_id, grader_model, framework_version, pipeline_version),
  CHECK (is_duplicate = (duplicate_of_session_id IS NOT NULL)),
  CHECK (duplicate_of_session_id IS DISTINCT FROM session_id),
  CHECK ((status = 'failed') = (failure_class IS NOT NULL)),
  CHECK (status <> 'mismatch' OR is_mismatch),
  CHECK (is_ran_out_of_time IS NULL OR is_time_remained IS NOT NULL AND is_ran_out_of_time <> is_time_remained)
);
COMMENT ON TABLE coachip_session_facts IS 'One row per (session, grader, framework, pipeline version): population flags, cause split and provenance (NIGHTLY_JOB stage 1). The only teacher reference is teacher_key. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_session_facts.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_session_facts.session_id IS '[Internal] the recorded lesson';
COMMENT ON COLUMN coachip_session_facts.teacher_key IS '[Confidential] hex(HMAC-SHA256(COACHIP_TEACHER_KEY_SECRET, coachip-teacher:users.id))[0:16] (API.md A13); server only, never in a payload';
COMMENT ON COLUMN coachip_session_facts.school_id IS '[Internal] the teacher''s current school when computed (E7)';
COMMENT ON COLUMN coachip_session_facts.sector IS '[Internal] schools.region of that school';
COMMENT ON COLUMN coachip_session_facts.recorded_at IS '[Internal] coaching_sessions.created_at (UTC); weeks are cut in Asia/Karachi';
COMMENT ON COLUMN coachip_session_facts.is_observed IS '[Internal] true = coach visit (leader_observation), false = self-recording';
COMMENT ON COLUMN coachip_session_facts.job_run_id IS '[Internal] the run that wrote the row';
COMMENT ON COLUMN coachip_session_facts.grader_model IS '[Internal] provenance: lp_fidelity.model (or the FICO scorer''s model) the number was graded by (B14)';
COMMENT ON COLUMN coachip_session_facts.framework_version IS '[Internal] provenance: instrument and version, e.g. fico_v3 or lp_fidelity (B19)';
COMMENT ON COLUMN coachip_session_facts.pipeline_version IS '[Internal] provenance: the nightly job''s semantic version; a change starts a new series (B19)';
COMMENT ON COLUMN coachip_session_facts.input_hash IS '[Internal] sha256 of the allow-listed inputs (idempotency)';
COMMENT ON COLUMN coachip_session_facts.status IS '[Internal] ok / insufficient / failed / mismatch';
COMMENT ON COLUMN coachip_session_facts.failure_class IS '[Internal] set when status = failed';
COMMENT ON COLUMN coachip_session_facts.is_mismatch IS '[Internal] lp_fidelity.moderators.note = lesson_mismatch';
COMMENT ON COLUMN coachip_session_facts.is_unusable IS '[Internal] lp_fidelity.recording_unusable IS TRUE';
COMMENT ON COLUMN coachip_session_facts.is_duplicate IS '[Internal] same audio_hash as a kept session';
COMMENT ON COLUMN coachip_session_facts.duplicate_of_session_id IS '[Internal] the kept session when is_duplicate';
COMMENT ON COLUMN coachip_session_facts.is_lp_linked IS '[Internal] lp_fidelity.status = ok: a plan was linked and graded (coverage n; API.md §12)';
COMMENT ON COLUMN coachip_session_facts.subject IS '[Internal] lesson subject from lp_fidelity.meta or analysis_data.subject';
COMMENT ON COLUMN coachip_session_facts.grade IS '[Internal] lesson grade';
COMMENT ON COLUMN coachip_session_facts.lesson_type IS '[Internal] S11 gate for the literacy rows';
COMMENT ON COLUMN coachip_session_facts.audio_s IS '[Internal] lp_fidelity.recording.audio_s';
COMMENT ON COLUMN coachip_session_facts.ends_at_s IS '[Internal] lp_fidelity.recording.ends_at in seconds';
COMMENT ON COLUMN coachip_session_facts.last_stamp_s IS '[Internal] lp_fidelity.recording.last_stamp_s';
COMMENT ON COLUMN coachip_session_facts.last_done_s IS '[Internal] largest stamp of an executed/substituted/partial move';
COMMENT ON COLUMN coachip_session_facts.is_short_of_audio IS '[Internal] lp_fidelity.recording.transcript_short_of_audio';
COMMENT ON COLUMN coachip_session_facts.is_ran_out_of_time IS '[Internal] cause split (WEAKNESS_MAP §A); null when not computable';
COMMENT ON COLUMN coachip_session_facts.is_time_remained IS '[Internal] NOT is_ran_out_of_time when computable';
COMMENT ON COLUMN coachip_session_facts.is_sent_home IS '[Internal] homework leg of W-IP-HOME held';
COMMENT ON COLUMN coachip_session_facts.is_stamped IS '[Internal] false when recording.no_timestamps or no stamp parsed (moment confidence none)';
COMMENT ON COLUMN coachip_session_facts.computed_at IS '[Internal] when the job computed the row (UTC)';
COMMENT ON COLUMN coachip_session_facts.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_session_facts.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_session_facts_updated_at ON coachip_session_facts;
CREATE TRIGGER coachip_session_facts_updated_at BEFORE UPDATE ON coachip_session_facts FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_session_facts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_session_facts ON coachip_session_facts;
CREATE POLICY service_role_coachip_session_facts ON coachip_session_facts FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_session_facts TO service_role;
CREATE INDEX IF NOT EXISTS idx_coachip_facts_school_recorded ON coachip_session_facts (school_id, recorded_at);
CREATE INDEX IF NOT EXISTS idx_coachip_facts_sector_recorded ON coachip_session_facts (sector, recorded_at);
CREATE INDEX IF NOT EXISTS idx_coachip_facts_teacher_recorded ON coachip_session_facts (teacher_key, recorded_at);

-- ── coachip_model_runs ─────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_model_runs (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id                 uuid NOT NULL REFERENCES coaching_sessions (id),
  job_run_id                 uuid NOT NULL REFERENCES coachip_job_runs (id),
  analysis                   coachip_analysis NOT NULL,
  target                     text NOT NULL DEFAULT '-' CHECK (target ~ '^(-|m[0-9]{1,2}|[A-F][0-9]{1,2})$'),
  purpose                    coachip_run_purpose NOT NULL DEFAULT 'primary',
  model                      text NOT NULL CHECK (model ~ '^[a-z0-9-]+/[a-z0-9.:-]+$'),
  prompt_version             text NOT NULL CHECK (prompt_version ~ '^(gloss|phonics|homework)_v[0-9]+$'),
  input_hash                 text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  status                     coachip_run_status NOT NULL,
  failure_class              coachip_failure_class,
  output                     jsonb,
  tokens_in                  integer NOT NULL DEFAULT 0 CHECK (tokens_in >= 0),
  tokens_out                 integer NOT NULL DEFAULT 0 CHECK (tokens_out >= 0),
  cost_usd                   numeric(8,5) NOT NULL DEFAULT 0 CHECK (cost_usd >= 0),
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (session_id, analysis, target, model, prompt_version, input_hash, purpose),
  CHECK (output IS NULL OR NOT jsonb_path_exists(output, '$.**.quote')),
  CHECK (status NOT IN ('blocked','failed') OR failure_class IS NOT NULL)
);
COMMENT ON TABLE coachip_model_runs IS 'One row per model call (x-analysis ANALYSES §4): model, prompt version, tokens, cost, gated output with quotes stripped. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_model_runs.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_model_runs.session_id IS '[Internal] the session the call read';
COMMENT ON COLUMN coachip_model_runs.job_run_id IS '[Internal] the night it ran';
COMMENT ON COLUMN coachip_model_runs.analysis IS '[Internal] gloss / phonics / homework';
COMMENT ON COLUMN coachip_model_runs.target IS '[Internal] the move id (m7) or FICO id the call is about; ''-'' for a whole session';
COMMENT ON COLUMN coachip_model_runs.purpose IS '[Internal] primary / fallback / recheck / drift_audit';
COMMENT ON COLUMN coachip_model_runs.model IS '[Internal] OpenRouter model id, e.g. openai/gpt-6-luna';
COMMENT ON COLUMN coachip_model_runs.prompt_version IS '[Internal] prompt file version';
COMMENT ON COLUMN coachip_model_runs.input_hash IS '[Internal] sha256 of the exact prompt input';
COMMENT ON COLUMN coachip_model_runs.status IS '[Internal] ok / blocked / failed / not_applicable / pending';
COMMENT ON COLUMN coachip_model_runs.failure_class IS '[Internal] why blocked or failed';
COMMENT ON COLUMN coachip_model_runs.output IS '[Internal] parsed output after the code gates; never a quote, never a name (CHECK)';
COMMENT ON COLUMN coachip_model_runs.tokens_in IS '[Internal] usage.prompt_tokens';
COMMENT ON COLUMN coachip_model_runs.tokens_out IS '[Internal] usage.completion_tokens';
COMMENT ON COLUMN coachip_model_runs.cost_usd IS '[Internal] usage.cost as returned';
COMMENT ON COLUMN coachip_model_runs.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_model_runs.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_model_runs_updated_at ON coachip_model_runs;
CREATE TRIGGER coachip_model_runs_updated_at BEFORE UPDATE ON coachip_model_runs FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_model_runs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_model_runs ON coachip_model_runs;
CREATE POLICY service_role_coachip_model_runs ON coachip_model_runs FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_model_runs TO service_role;
CREATE INDEX IF NOT EXISTS idx_coachip_model_runs_job ON coachip_model_runs (job_run_id);

-- ── coachip_session_signals ────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_session_signals (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fact_id                    uuid NOT NULL REFERENCES coachip_session_facts (id) ON DELETE CASCADE,
  session_id                 uuid NOT NULL REFERENCES coaching_sessions (id),
  w_id                       text NOT NULL REFERENCES coachip_weaknesses (w_id),
  source                     coachip_signal_source NOT NULL,
  is_in_denominator          boolean NOT NULL,
  is_hit                     boolean NOT NULL,
  value                      smallint,
  stamp_s                    integer CHECK (stamp_s IS NULL OR stamp_s >= 0),
  model_run_id               uuid REFERENCES coachip_model_runs (id),
  status                     coachip_status NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (fact_id, w_id),
  CHECK (is_in_denominator OR NOT is_hit),
  CHECK (source <> 'coachip_detector' OR model_run_id IS NOT NULL)
);
COMMENT ON TABLE coachip_session_signals IS 'One row per W per session fact (NIGHTLY_JOB stage 2): in the W''s denominator or not, and a hit or not. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_session_signals.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_session_signals.fact_id IS '[Internal] the session fact';
COMMENT ON COLUMN coachip_session_signals.session_id IS '[Internal] denormalised for the check strip';
COMMENT ON COLUMN coachip_session_signals.w_id IS '[Internal] the W';
COMMENT ON COLUMN coachip_session_signals.source IS '[Internal] instrument read (the W''s primary for this window)';
COMMENT ON COLUMN coachip_session_signals.is_in_denominator IS '[Internal] the lesson''s plan asked for the step / the indicator was applicable';
COMMENT ON COLUMN coachip_session_signals.is_hit IS '[Internal] the W''s primary predicate held';
COMMENT ON COLUMN coachip_session_signals.value IS '[Internal] indicator score or detector F8 value; null for a phase';
COMMENT ON COLUMN coachip_session_signals.stamp_s IS '[Internal] second used for the moment, when any';
COMMENT ON COLUMN coachip_session_signals.model_run_id IS '[Internal] the detector call behind a coachip_detector signal';
COMMENT ON COLUMN coachip_session_signals.status IS '[Internal] ok / insufficient / failed / mismatch';
COMMENT ON COLUMN coachip_session_signals.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_session_signals.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_session_signals_updated_at ON coachip_session_signals;
CREATE TRIGGER coachip_session_signals_updated_at BEFORE UPDATE ON coachip_session_signals FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_session_signals ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_session_signals ON coachip_session_signals;
CREATE POLICY service_role_coachip_session_signals ON coachip_session_signals FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_session_signals TO service_role;
CREATE INDEX IF NOT EXISTS idx_coachip_signals_w_session ON coachip_session_signals (w_id, session_id);

-- ── coachip_moments ────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_moments (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fact_id                    uuid NOT NULL REFERENCES coachip_session_facts (id) ON DELETE CASCADE,
  session_id                 uuid NOT NULL REFERENCES coaching_sessions (id),
  w_id                       text NOT NULL REFERENCES coachip_weaknesses (w_id),
  kind                       coachip_moment_kind NOT NULL,
  move_id                    text CHECK (move_id IS NULL OR move_id ~ '^m[0-9]{1,2}$'),
  phase                      text CHECK (phase IS NULL OR phase ~ '^[a-z_]+$'),
  from_s                     integer NOT NULL CHECK (from_s >= 0),
  to_s                       integer NOT NULL,
  moment_s                   integer CHECK (moment_s IS NULL OR moment_s >= 0),
  confidence                 coachip_confidence NOT NULL,
  credit                     numeric(3,2) CHECK (credit IS NULL OR credit BETWEEN 0 AND 1),
  gloss_en                   text CHECK (gloss_en IS NULL OR length(gloss_en) <= 90),
  gloss_ur                   text CHECK (gloss_ur IS NULL OR length(gloss_ur) <= 70),
  gloss_status               coachip_gloss_status NOT NULL DEFAULT 'pending',
  gloss_model_run_id         uuid REFERENCES coachip_model_runs (id),
  clip_r2_key                text CHECK (clip_r2_key IS NULL OR clip_r2_key ~ '^coachip/clips/(sandbox|staging|production)/[0-9a-f-]{36}/[0-9]+-[0-9]+\.mp3$'),
  clip_status                coachip_clip_status NOT NULL DEFAULT 'pending',
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (fact_id, w_id, kind),
  CHECK (to_s > from_s AND to_s - from_s <= 90),
  CHECK ((gloss_status = 'ok') = (gloss_en IS NOT NULL AND gloss_ur IS NOT NULL)),
  CHECK (gloss_status <> 'ok' OR gloss_model_run_id IS NOT NULL),
  CHECK (clip_status <> 'ready' OR clip_r2_key IS NOT NULL),
  CHECK (confidence <> 'none' OR gloss_status IN ('not_applicable','not_evaluated'))
);
COMMENT ON TABLE coachip_moments IS 'A playable moment per (fact, W, kind) (DESIGN §5): seconds, confidence, gated gloss, pre-cut clip key. Never a quote. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_moments.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_moments.fact_id IS '[Internal] the session fact';
COMMENT ON COLUMN coachip_moments.session_id IS '[Internal] the recording';
COMMENT ON COLUMN coachip_moments.w_id IS '[Internal] the W the moment shows';
COMMENT ON COLUMN coachip_moments.kind IS '[Internal] missing / good / phonics';
COMMENT ON COLUMN coachip_moments.move_id IS '[Internal] lp_fidelity move id the moment is cut on';
COMMENT ON COLUMN coachip_moments.phase IS '[Internal] the plan step''s phase';
COMMENT ON COLUMN coachip_moments.from_s IS '[Internal] clip start in the recording (s)';
COMMENT ON COLUMN coachip_moments.to_s IS '[Internal] clip end (s); at most 90 s after from_s';
COMMENT ON COLUMN coachip_moments.moment_s IS '[Internal] the stamp itself (''in the lesson 18:42'')';
COMMENT ON COLUMN coachip_moments.confidence IS '[Internal] high (stamped move or indicator) / medium (skipped move) / none';
COMMENT ON COLUMN coachip_moments.credit IS '[Internal] move credit, used to pick the pair';
COMMENT ON COLUMN coachip_moments.gloss_en IS '[Internal] gated one-line gloss, English, code prefix included';
COMMENT ON COLUMN coachip_moments.gloss_ur IS '[Internal] gated one-line gloss, Urdu';
COMMENT ON COLUMN coachip_moments.gloss_status IS '[Internal] ok / blocked / failed / not_applicable / pending / not_evaluated / paused';
COMMENT ON COLUMN coachip_moments.gloss_model_run_id IS '[Internal] the call that wrote the gloss (model and prompt version live there)';
COMMENT ON COLUMN coachip_moments.clip_r2_key IS '[Internal] R2 object key of the pre-cut clip; carries no teacher identifier';
COMMENT ON COLUMN coachip_moments.clip_status IS '[Internal] ready / pending / failed / expired';
COMMENT ON COLUMN coachip_moments.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_moments.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_moments_updated_at ON coachip_moments;
CREATE TRIGGER coachip_moments_updated_at BEFORE UPDATE ON coachip_moments FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_moments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_moments ON coachip_moments;
CREATE POLICY service_role_coachip_moments ON coachip_moments FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_moments TO service_role;
CREATE INDEX IF NOT EXISTS idx_coachip_moments_session ON coachip_moments (session_id);
CREATE INDEX IF NOT EXISTS idx_coachip_moments_w_kind ON coachip_moments (w_id, kind);

-- ── coachip_session_steps ──────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_session_steps (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fact_id                    uuid NOT NULL REFERENCES coachip_session_facts (id) ON DELETE CASCADE,
  ordinal                    smallint NOT NULL CHECK (ordinal >= 1),
  move_id                    text NOT NULL CHECK (move_id ~ '^m[0-9]{1,2}$'),
  phase                      text NOT NULL CHECK (phase ~ '^[a-z_]+$'),
  verdict                    coachip_step_verdict NOT NULL,
  is_counted                 boolean NOT NULL,
  from_s                     integer CHECK (from_s IS NULL OR from_s >= 0),
  to_s                       integer,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (fact_id, ordinal),
  UNIQUE (fact_id, move_id),
  CHECK ((from_s IS NULL) = (to_s IS NULL)),
  CHECK (to_s IS NULL OR to_s > from_s)
);
COMMENT ON TABLE coachip_session_steps IS 'The S4 chapter strip (API.md §3 Moment.steps[]): one row per plan step of a graded session, its verdict and seconds. No step text, no quote. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_session_steps.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_session_steps.fact_id IS '[Internal] the session fact';
COMMENT ON COLUMN coachip_session_steps.ordinal IS '[Internal] position in the plan';
COMMENT ON COLUMN coachip_session_steps.move_id IS '[Internal] lp_fidelity move id';
COMMENT ON COLUMN coachip_session_steps.phase IS '[Internal] the step''s phase; the label comes from COPY by phase';
COMMENT ON COLUMN coachip_session_steps.verdict IS '[Internal] collapsed verdict for the strip';
COMMENT ON COLUMN coachip_session_steps.is_counted IS '[Internal] moves[].counted (the required-move rule, O5)';
COMMENT ON COLUMN coachip_session_steps.from_s IS '[Internal] the step''s [MM:SS] stamp in seconds; null when not stamped';
COMMENT ON COLUMN coachip_session_steps.to_s IS '[Internal] next stamp or recording end; null when from_s is null';
COMMENT ON COLUMN coachip_session_steps.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_session_steps.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_session_steps_updated_at ON coachip_session_steps;
CREATE TRIGGER coachip_session_steps_updated_at BEFORE UPDATE ON coachip_session_steps FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_session_steps ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_session_steps ON coachip_session_steps;
CREATE POLICY service_role_coachip_session_steps ON coachip_session_steps FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_session_steps TO service_role;

-- ── coachip_rollups ────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_rollups (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scope_kind                 coachip_scope_kind NOT NULL,
  coach_user_id              uuid REFERENCES users (id),
  school_id                  uuid REFERENCES schools (id),
  sector                     text CHECK (sector IS NULL OR sector IN ('B.K','Sihala','Urban-I','Nilore','Urban-II','Tarnol')),
  scope_id                   text GENERATED ALWAYS AS (COALESCE(coach_user_id::text, school_id::text, sector)) STORED,
  w_id                       text NOT NULL REFERENCES coachip_weaknesses (w_id),
  window_start               date NOT NULL,
  window_end                 date NOT NULL,
  window_weeks               smallint NOT NULL CHECK (window_weeks IN (4, 8)),
  numerator                  integer NOT NULL CHECK (numerator >= 0),
  denominator                integer NOT NULL CHECK (denominator >= 0),
  numerator_observed         integer NOT NULL DEFAULT 0 CHECK (numerator_observed >= 0),
  denominator_observed       integer NOT NULL DEFAULT 0 CHECK (denominator_observed >= 0),
  teacher_count              integer NOT NULL CHECK (teacher_count >= 0),
  coach_count                integer NOT NULL DEFAULT 1 CHECK (coach_count >= 0),
  coaches_with_5plus         integer NOT NULL DEFAULT 1 CHECK (coaches_with_5plus >= 0),
  excluded_mismatch          integer NOT NULL DEFAULT 0 CHECK (excluded_mismatch >= 0),
  excluded_unusable          integer NOT NULL DEFAULT 0 CHECK (excluded_unusable >= 0),
  excluded_duplicate         integer NOT NULL DEFAULT 0 CHECK (excluded_duplicate >= 0),
  excluded_failed            integer NOT NULL DEFAULT 0 CHECK (excluded_failed >= 0),
  recordings                 integer NOT NULL DEFAULT 0 CHECK (recordings >= 0),
  recordings_linked          integer NOT NULL DEFAULT 0 CHECK (recordings_linked >= 0),
  stat_kind                  coachip_stat_kind,
  stat_unit                  coachip_stat_unit,
  stat_value                 numeric(6,1),
  stat_base                  integer CHECK (stat_base IS NULL OR stat_base >= 0),
  rank                       smallint CHECK (rank IS NULL OR rank IN (1, 2)),
  product                    numeric(6,4) CHECK (product IS NULL OR product >= 0),
  is_hysteresis_applied      boolean NOT NULL DEFAULT false,
  grader_model               text NOT NULL CHECK (length(grader_model) BETWEEN 1 AND 120),
  framework_version          text NOT NULL CHECK (framework_version ~ '^(lp_fidelity|fico_v3|fico_v4|fico17|coachip_detector|egra|code)(:[A-Za-z0-9._-]+)?$'),
  pipeline_version           text NOT NULL CHECK (pipeline_version ~ '^coachip-[0-9]+\.[0-9]+\.[0-9]+$'),
  status                     coachip_status NOT NULL,
  job_run_id                 uuid NOT NULL REFERENCES coachip_job_runs (id),
  computed_at                timestamptz NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  CHECK ((scope_kind = 'coach'  AND coach_user_id IS NOT NULL AND school_id IS NULL AND sector IS NULL) OR (scope_kind = 'school' AND school_id IS NOT NULL AND coach_user_id IS NULL AND sector IS NULL) OR (scope_kind = 'sector' AND sector IS NOT NULL AND coach_user_id IS NULL AND school_id IS NULL)),
  UNIQUE (scope_kind, scope_id, w_id, window_start, window_end, grader_model, framework_version, pipeline_version),
  CHECK (numerator <= denominator AND numerator_observed <= numerator AND denominator_observed <= denominator),
  CHECK (recordings_linked <= recordings),
  CHECK (window_end = window_start + (7 * window_weeks - 1)),
  CHECK (EXTRACT(ISODOW FROM window_start) = 1),
  CHECK ((stat_kind IS NULL) = (stat_value IS NULL) AND (stat_kind IS NULL) = (stat_base IS NULL) AND (stat_kind IS NULL) = (stat_unit IS NULL)),
  CHECK (status <> 'ok' OR scope_kind <> 'sector' OR (denominator >= 40 AND coaches_with_5plus >= 3)),
  CHECK (status <> 'ok' OR scope_kind <> 'coach' OR denominator >= 20),
  CHECK (rank IS NULL OR status = 'ok')
);
COMMENT ON TABLE coachip_rollups IS 'Per scope, W and window: n of d with exclusions, floors, the B23 columns, the derived statistic and the rank (NIGHTLY_JOB stages 6-7). Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_rollups.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_rollups.scope_kind IS '[Internal] coach / school / sector';
COMMENT ON COLUMN coachip_rollups.coach_user_id IS '[Internal] the coach (staff user) when scope_kind = coach; never a teacher';
COMMENT ON COLUMN coachip_rollups.school_id IS '[Internal] the school when scope_kind = school';
COMMENT ON COLUMN coachip_rollups.sector IS '[Internal] the sector literal when scope_kind = sector';
COMMENT ON COLUMN coachip_rollups.scope_id IS '[Internal] one key for the three scope columns (generated)';
COMMENT ON COLUMN coachip_rollups.w_id IS '[Internal] the W';
COMMENT ON COLUMN coachip_rollups.window_start IS '[Internal] first Monday of the window (Asia/Karachi)';
COMMENT ON COLUMN coachip_rollups.window_end IS '[Internal] last Sunday of the window';
COMMENT ON COLUMN coachip_rollups.window_weeks IS '[Internal] 4 at >= floor, else 8';
COMMENT ON COLUMN coachip_rollups.numerator IS '[Internal] lessons where the W held (n)';
COMMENT ON COLUMN coachip_rollups.denominator IS '[Internal] lessons in the W''s denominator (d)';
COMMENT ON COLUMN coachip_rollups.numerator_observed IS '[Internal] n from coach visits only (self-recorded n = numerator - this)';
COMMENT ON COLUMN coachip_rollups.denominator_observed IS '[Internal] d from coach visits only';
COMMENT ON COLUMN coachip_rollups.teacher_count IS '[Internal] distinct teacher keys with a hit (the >= 3 codes leg)';
COMMENT ON COLUMN coachip_rollups.coach_count IS '[Internal] coaches contributing (B23)';
COMMENT ON COLUMN coachip_rollups.coaches_with_5plus IS '[Internal] coaches with >= 5 in-denominator lessons (B23)';
COMMENT ON COLUMN coachip_rollups.excluded_mismatch IS '[Internal] lessons dropped as lesson_mismatch';
COMMENT ON COLUMN coachip_rollups.excluded_unusable IS '[Internal] lessons dropped as recording_unusable';
COMMENT ON COLUMN coachip_rollups.excluded_duplicate IS '[Internal] lessons dropped as duplicate audio';
COMMENT ON COLUMN coachip_rollups.excluded_failed IS '[Internal] lessons whose analysis failed';
COMMENT ON COLUMN coachip_rollups.recordings IS '[Internal] all recordings in scope and window (coverage d)';
COMMENT ON COLUMN coachip_rollups.recordings_linked IS '[Internal] recordings with a graded plan (coverage n)';
COMMENT ON COLUMN coachip_rollups.stat_kind IS '[Internal] derived statistic kind (B5 add)';
COMMENT ON COLUMN coachip_rollups.stat_unit IS '[Internal] its unit';
COMMENT ON COLUMN coachip_rollups.stat_value IS '[Internal] its value';
COMMENT ON COLUMN coachip_rollups.stat_base IS '[Internal] its base, said once as a clause';
COMMENT ON COLUMN coachip_rollups.rank IS '[Internal] S1/S8 move rank after hysteresis';
COMMENT ON COLUMN coachip_rollups.product IS '[Internal] prevalence x weight used for the rank';
COMMENT ON COLUMN coachip_rollups.is_hysteresis_applied IS '[Internal] last window''s order kept (top two within 10%)';
COMMENT ON COLUMN coachip_rollups.grader_model IS '[Internal] provenance: lp_fidelity.model (or the FICO scorer''s model) the number was graded by (B14)';
COMMENT ON COLUMN coachip_rollups.framework_version IS '[Internal] provenance: instrument and version, e.g. fico_v3 or lp_fidelity (B19)';
COMMENT ON COLUMN coachip_rollups.pipeline_version IS '[Internal] provenance: the nightly job''s semantic version; a change starts a new series (B19)';
COMMENT ON COLUMN coachip_rollups.status IS '[Internal] ok, or insufficient below the floor (20 coach, 40 + B23 sector)';
COMMENT ON COLUMN coachip_rollups.job_run_id IS '[Internal] the run that wrote it';
COMMENT ON COLUMN coachip_rollups.computed_at IS '[Internal] when computed (UTC)';
COMMENT ON COLUMN coachip_rollups.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_rollups.updated_at IS '[Internal] row last changed (UTC); set by trigger';
