CREATE TRIGGER coachip_rollups_updated_at BEFORE UPDATE ON coachip_rollups FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_rollups ENABLE ROW LEVEL SECURITY;
