-- ── coachip_phonics_state ──────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_phonics_state (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  detector_model             text NOT NULL CHECK (detector_model ~ '^[a-z0-9-]+/[a-z0-9.:-]+$'),
  prompt_version             text NOT NULL CHECK (prompt_version ~ '^phonics_v[0-9]+$'),
  state                      coachip_phonics_gate NOT NULL DEFAULT 'testing',
  read_count                 integer NOT NULL DEFAULT 0 CHECK (read_count BETWEEN 0 AND 30),
  kappa                      numeric(3,2) CHECK (kappa IS NULL OR kappa BETWEEN -1 AND 1),
  is_kappa_passed            boolean NOT NULL DEFAULT false,
  signed_off_by              uuid REFERENCES users (id),
  signed_off_at              timestamptz,
  paused_by                  uuid REFERENCES users (id),
  paused_at                  timestamptz,
  pause_reason               coachip_failure_class,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (detector_model, prompt_version),
  CHECK (is_kappa_passed = (kappa IS NOT NULL AND kappa >= 0.80 AND read_count = 30)),
  CHECK (state <> 'ok' OR (is_kappa_passed AND signed_off_by IS NOT NULL)),
  CHECK ((state = 'paused') = (paused_at IS NOT NULL))
);
COMMENT ON TABLE coachip_phonics_state IS 'The phonics detector''s gate, per detector model and prompt version (O8): testing until kappa >= 0.80 on the blind 30, then ok; a person may pause. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_phonics_state.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_phonics_state.detector_model IS '[Internal] e.g. anthropic/claude-haiku-5.5';
COMMENT ON COLUMN coachip_phonics_state.prompt_version IS '[Internal] e.g. phonics_v2';
COMMENT ON COLUMN coachip_phonics_state.state IS '[Internal] testing / ok / paused';
COMMENT ON COLUMN coachip_phonics_state.read_count IS '[Internal] blind-set recordings a person has read (n of 30)';
COMMENT ON COLUMN coachip_phonics_state.kappa IS '[Internal] Cohen''s kappa, detector vs the human read';
COMMENT ON COLUMN coachip_phonics_state.is_kappa_passed IS '[Internal] kappa >= 0.80 on all 30';
COMMENT ON COLUMN coachip_phonics_state.signed_off_by IS '[Internal] staff user who signed the gate off';
COMMENT ON COLUMN coachip_phonics_state.signed_off_at IS '[Internal] when (UTC)';
COMMENT ON COLUMN coachip_phonics_state.paused_by IS '[Internal] staff user who paused it';
COMMENT ON COLUMN coachip_phonics_state.paused_at IS '[Internal] when (UTC)';
COMMENT ON COLUMN coachip_phonics_state.pause_reason IS '[Internal] drift-audit result or a person''s pause';
COMMENT ON COLUMN coachip_phonics_state.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_phonics_state.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_phonics_state_updated_at ON coachip_phonics_state;
CREATE TRIGGER coachip_phonics_state_updated_at BEFORE UPDATE ON coachip_phonics_state FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_phonics_state ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_phonics_state ON coachip_phonics_state;
CREATE POLICY service_role_coachip_phonics_state ON coachip_phonics_state FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_phonics_state TO service_role;

-- ── coachip_result_cells ───────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_result_cells (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  school_id                  uuid NOT NULL REFERENCES schools (id),
  grade                      smallint NOT NULL CHECK (grade BETWEEN 1 AND 5),
  language                   coachip_language NOT NULL,
  w_id                       text NOT NULL REFERENCES coachip_weaknesses (w_id),
  term_start                 date NOT NULL,
  tested                     integer NOT NULL CHECK (tested >= 0),
  numerator                  integer CHECK (numerator IS NULL OR numerator >= 0),
  status                     coachip_cell_status NOT NULL,
  grader_model               text NOT NULL CHECK (length(grader_model) BETWEEN 1 AND 120),
  framework_version          text NOT NULL CHECK (framework_version ~ '^(lp_fidelity|fico_v3|fico_v4|fico17|coachip_detector|egra|code)(:[A-Za-z0-9._-]+)?$'),
  pipeline_version           text NOT NULL CHECK (pipeline_version ~ '^coachip-[0-9]+\.[0-9]+\.[0-9]+$'),
  job_run_id                 uuid NOT NULL REFERENCES coachip_job_runs (id),
  computed_at                timestamptz NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (school_id, grade, language, w_id, term_start, pipeline_version),
  CHECK ((status = 'ok') = (numerator IS NOT NULL)),
  CHECK (status <> 'ok' OR tested >= 5),
  CHECK (numerator IS NULL OR numerator <= tested)
);
COMMENT ON TABLE coachip_result_cells IS 'S7 child-result cells per (school, grade, language, W) for the term (B20): never a teacher, never under 5 tested, never a test account. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_result_cells.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_result_cells.school_id IS '[Internal] the school';
COMMENT ON COLUMN coachip_result_cells.grade IS '[Internal] the grade tested';
COMMENT ON COLUMN coachip_result_cells.language IS '[Internal] test language';
COMMENT ON COLUMN coachip_result_cells.w_id IS '[Internal] the child-result W (W-LS, W-FW, W-LN ...)';
COMMENT ON COLUMN coachip_result_cells.term_start IS '[Internal] first day of the term window';
COMMENT ON COLUMN coachip_result_cells.tested IS '[Internal] children tested in the cell';
COMMENT ON COLUMN coachip_result_cells.numerator IS '[Internal] children below the bar; null unless status ok';
COMMENT ON COLUMN coachip_result_cells.status IS '[Internal] ok / insufficient / not_measured / not_graded';
COMMENT ON COLUMN coachip_result_cells.grader_model IS '[Internal] provenance: lp_fidelity.model (or the FICO scorer''s model) the number was graded by (B14)';
COMMENT ON COLUMN coachip_result_cells.framework_version IS '[Internal] provenance: instrument and version, e.g. fico_v3 or lp_fidelity (B19)';
COMMENT ON COLUMN coachip_result_cells.pipeline_version IS '[Internal] provenance: the nightly job''s semantic version; a change starts a new series (B19)';
COMMENT ON COLUMN coachip_result_cells.job_run_id IS '[Internal] the run that wrote it';
COMMENT ON COLUMN coachip_result_cells.computed_at IS '[Internal] when computed (UTC)';
COMMENT ON COLUMN coachip_result_cells.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_result_cells.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_result_cells_updated_at ON coachip_result_cells;
CREATE TRIGGER coachip_result_cells_updated_at BEFORE UPDATE ON coachip_result_cells FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_result_cells ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_result_cells ON coachip_result_cells;
CREATE POLICY service_role_coachip_result_cells ON coachip_result_cells FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_result_cells TO service_role;
CREATE INDEX IF NOT EXISTS idx_coachip_cells_school ON coachip_result_cells (school_id, term_start DESC);

-- ── coachip_teacher_codes ──────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_teacher_codes (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  coach_user_id              uuid NOT NULL REFERENCES users (id),
  teacher_key                text NOT NULL CHECK (teacher_key ~ '^[0-9a-f]{16}$'),
  ordinal                    integer NOT NULL CHECK (ordinal > 0),
  code                       text GENERATED ALWAYS AS ('T-' || lpad(ordinal::text, 2, '0')) STORED,
  assigned_at                timestamptz NOT NULL DEFAULT now(),
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (coach_user_id, teacher_key),
  UNIQUE (coach_user_id, ordinal)
);
COMMENT ON TABLE coachip_teacher_codes IS 'The per-coach code space (SPEC §8, B21): code_id is the only handle a client holds; the ordinal is never reassigned. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_teacher_codes.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_teacher_codes.coach_user_id IS '[Internal] the coach (staff) the code belongs to';
COMMENT ON COLUMN coachip_teacher_codes.teacher_key IS '[Confidential] HMAC teacher pseudonym; server only';
COMMENT ON COLUMN coachip_teacher_codes.ordinal IS '[Internal] the per-coach number';
COMMENT ON COLUMN coachip_teacher_codes.code IS '[Internal] the display code, e.g. T-07 (generated)';
COMMENT ON COLUMN coachip_teacher_codes.assigned_at IS '[Internal] first appearance in the coach''s scope (UTC)';
COMMENT ON COLUMN coachip_teacher_codes.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_teacher_codes.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_teacher_codes_updated_at ON coachip_teacher_codes;
CREATE TRIGGER coachip_teacher_codes_updated_at BEFORE UPDATE ON coachip_teacher_codes FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_teacher_codes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_teacher_codes ON coachip_teacher_codes;
CREATE POLICY service_role_coachip_teacher_codes ON coachip_teacher_codes FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_teacher_codes TO service_role;
CREATE OR REPLACE FUNCTION coachip_codes_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' OR NEW.coach_user_id <> OLD.coach_user_id OR NEW.teacher_key <> OLD.teacher_key OR NEW.ordinal <> OLD.ordinal THEN
    RAISE EXCEPTION 'coachip_teacher_codes: a code is never reassigned or removed';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS coachip_codes_immutable ON coachip_teacher_codes;
CREATE TRIGGER coachip_codes_immutable BEFORE UPDATE OR DELETE ON coachip_teacher_codes FOR EACH ROW EXECUTE FUNCTION coachip_codes_immutable();

-- ── coachip_audit_log ──────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_audit_log (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_user_id              uuid NOT NULL REFERENCES users (id),
  action                     coachip_audit_action NOT NULL,
  subject_id                 uuid NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE coachip_audit_log IS 'Append-only record of every decode, clip, full-recording, note and circle play (D20). No UPDATE or DELETE grant; a trigger refuses both. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_audit_log.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_audit_log.actor_user_id IS '[Internal] the coach or RM (staff) who acted';
COMMENT ON COLUMN coachip_audit_log.action IS '[Internal] decode / clip / full_audio / note_sent / circle_play';
COMMENT ON COLUMN coachip_audit_log.subject_id IS '[Internal] the code_id, moment id, session id or note id acted on; never a key or a name (polymorphic, so no FK)';
COMMENT ON COLUMN coachip_audit_log.created_at IS '[Internal] when (UTC)';
ALTER TABLE coachip_audit_log ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_audit_log ON coachip_audit_log;
CREATE POLICY service_role_coachip_audit_log ON coachip_audit_log FOR ALL USING (auth.role() = 'service_role');
GRANT SELECT, INSERT ON coachip_audit_log TO service_role;
CREATE INDEX IF NOT EXISTS idx_coachip_audit_actor ON coachip_audit_log (actor_user_id, created_at DESC);
CREATE OR REPLACE FUNCTION coachip_audit_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'coachip_audit_log is append-only';
END $$;
DROP TRIGGER IF EXISTS coachip_audit_append_only ON coachip_audit_log;
CREATE TRIGGER coachip_audit_append_only BEFORE UPDATE OR DELETE ON coachip_audit_log FOR EACH ROW EXECUTE FUNCTION coachip_audit_append_only();
DROP TRIGGER IF EXISTS coachip_audit_no_wipe ON coachip_audit_log;
-- destructive: reviewed — the keyword below is a guard that REFUSES a wipe of the audit log, not a wipe.
CREATE TRIGGER coachip_audit_no_wipe BEFORE TRUNCATE ON coachip_audit_log FOR EACH STATEMENT EXECUTE FUNCTION coachip_audit_append_only();
-- destructive: reviewed — removes the right to change or wipe the audit log (D20); destroys nothing.
REVOKE UPDATE, DELETE, TRUNCATE ON coachip_audit_log FROM PUBLIC, anon, authenticated, service_role;

