-- ── coachip_steps ──────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_steps (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  coach_user_id              uuid NOT NULL REFERENCES users (id),
