  i_id                       text NOT NULL REFERENCES coachip_interventions (i_id),
  source_session_id          uuid REFERENCES coaching_sessions (id),
  source_moment_id           uuid REFERENCES coachip_moments (id),
  rm_note_id                 uuid REFERENCES coachip_rm_notes (id),
  set_at                     timestamptz NOT NULL DEFAULT now(),
  check_by                   date NOT NULL,
  check_by_rule              text NOT NULL CHECK (check_by_rule IN ('visit','14_days')),
  visit_schedule_id          uuid REFERENCES observation_schedules (id),
  status                     coachip_step_status NOT NULL DEFAULT 'open',
  coach_tick                 coachip_tick NOT NULL DEFAULT 'pending',
  checked_at                 timestamptz,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  CHECK (check_by >= (set_at AT TIME ZONE 'Asia/Karachi')::date + 7),
  CHECK (check_by_rule <> '14_days' OR check_by = (set_at AT TIME ZONE 'Asia/Karachi')::date + 14),
  CHECK ((check_by_rule = 'visit') = (visit_schedule_id IS NOT NULL)),
  CHECK ((scope = 'coach' AND code_id IS NOT NULL AND school_id IS NOT NULL) OR (scope = 'school' AND code_id IS NULL AND school_id IS NOT NULL) OR (scope = 'sector' AND code_id IS NULL AND sector IS NOT NULL)),
  CHECK ((coach_tick = 'pending') = (checked_at IS NULL))
);
COMMENT ON TABLE coachip_steps IS 'A coaching step set with one tap (DESIGN §6; SPEC v2 coach_steps renamed): who, which W and I, check-by date, status, the coach''s tick. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_steps.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_steps.coach_user_id IS '[Internal] the coach (or RM for a sector step) who set it';
COMMENT ON COLUMN coachip_steps.scope IS '[Internal] coach (a teacher step) / school / sector';
COMMENT ON COLUMN coachip_steps.code_id IS '[Internal] the teacher''s code in the setter''s code space; required for scope coach';
COMMENT ON COLUMN coachip_steps.school_id IS '[Internal] the school';
COMMENT ON COLUMN coachip_steps.sector IS '[Internal] the sector, for a sector step';
COMMENT ON COLUMN coachip_steps.w_id IS '[Internal] the W';
COMMENT ON COLUMN coachip_steps.i_id IS '[Internal] the intervention';
COMMENT ON COLUMN coachip_steps.source_session_id IS '[Internal] the recording the step was set from';
COMMENT ON COLUMN coachip_steps.source_moment_id IS '[Internal] the moment the step was set from';
COMMENT ON COLUMN coachip_steps.rm_note_id IS '[Internal] the RM note that prompted it';
COMMENT ON COLUMN coachip_steps.set_at IS '[Internal] when set (UTC)';
COMMENT ON COLUMN coachip_steps.check_by IS '[Internal] first booked visit >= 7 days away, else set date + 14 (Asia/Karachi)';
COMMENT ON COLUMN coachip_steps.check_by_rule IS '[Internal] which rule produced check_by';
COMMENT ON COLUMN coachip_steps.visit_schedule_id IS '[Internal] the booked visit when check_by_rule = visit';
COMMENT ON COLUMN coachip_steps.status IS '[Internal] open / completed / deferred / cancelled';
COMMENT ON COLUMN coachip_steps.coach_tick IS '[Internal] the coach''s own tick (primary check)';
COMMENT ON COLUMN coachip_steps.checked_at IS '[Internal] when the tick was given (UTC)';
COMMENT ON COLUMN coachip_steps.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_steps.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_steps_updated_at ON coachip_steps;
CREATE TRIGGER coachip_steps_updated_at BEFORE UPDATE ON coachip_steps FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_steps ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_steps ON coachip_steps;
CREATE POLICY service_role_coachip_steps ON coachip_steps FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_steps TO service_role;
CREATE UNIQUE INDEX IF NOT EXISTS uq_coachip_steps_open ON coachip_steps (coach_user_id, code_id, w_id) WHERE status = 'open' AND code_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_coachip_steps_coach_status ON coachip_steps (coach_user_id, status, check_by);

-- ── coachip_step_checks ────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS coachip_step_checks (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  step_id                    uuid NOT NULL REFERENCES coachip_steps (id) ON DELETE CASCADE,
  session_id                 uuid NOT NULL REFERENCES coaching_sessions (id),
  seq                        smallint NOT NULL CHECK (seq BETWEEN 1 AND 3),
  hit                        coachip_check_hit NOT NULL,
  recorded_at                timestamptz NOT NULL,
  job_run_id                 uuid NOT NULL REFERENCES coachip_job_runs (id),
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (step_id, session_id),
  UNIQUE (step_id, seq)
);
COMMENT ON TABLE coachip_step_checks IS 'The check strip (S14): each later graded recording within 14 days scored against the step''s check signal; 2 of 3 = worked. Owner: COACHIP / m-insights (bd-sex15q.14). Steward: c-insights (bd-sex15q.21) until the go; then the NIETE data steward named in the go package.';
COMMENT ON COLUMN coachip_step_checks.id IS '[Internal] row id (UUID v4)';
COMMENT ON COLUMN coachip_step_checks.step_id IS '[Internal] the step';
COMMENT ON COLUMN coachip_step_checks.session_id IS '[Internal] the later recording';
COMMENT ON COLUMN coachip_step_checks.seq IS '[Internal] 1st, 2nd or 3rd graded recording after set_at';
COMMENT ON COLUMN coachip_step_checks.hit IS '[Internal] hit / partial (progress, praised) / miss';
COMMENT ON COLUMN coachip_step_checks.recorded_at IS '[Internal] when the recording was made (UTC)';
COMMENT ON COLUMN coachip_step_checks.job_run_id IS '[Internal] the run that scored it';
COMMENT ON COLUMN coachip_step_checks.created_at IS '[Internal] row written (UTC)';
COMMENT ON COLUMN coachip_step_checks.updated_at IS '[Internal] row last changed (UTC); set by trigger';
DROP TRIGGER IF EXISTS coachip_step_checks_updated_at ON coachip_step_checks;
CREATE TRIGGER coachip_step_checks_updated_at BEFORE UPDATE ON coachip_step_checks FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
ALTER TABLE coachip_step_checks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS service_role_coachip_step_checks ON coachip_step_checks;
CREATE POLICY service_role_coachip_step_checks ON coachip_step_checks FOR ALL USING (auth.role() = 'service_role');
GRANT ALL ON coachip_step_checks TO service_role;


